const BODY_SEQ_8 = [0, 1, 2, 3, 4, 5, 6, 7];
const ORB_SEQ_6 = [0, 1, 2, 3, 4, 5];

export const THUNDER_DRAKE_EMPEROR_V2_DEF = Object.freeze({
  grid: THUNDER_DRAKE_EMPEROR_V2_GRID,
  materials: THUNDER_DRAKE_EMPEROR_V2_MATERIALS,
  parts: THUNDER_DRAKE_EMPEROR_V2_PARTS,
  animate({
    frame = 0,
    pose = 'idle',
    progress = 0,
    attacking = false,
    charging = false,
    hurt = false,
    reducedMotion = false,
    armor = null,
    grounded = false,
    reflecting = false,
    now = 0,
  }) {
    if (pose === 'dead') {
      return {
        materialOverrides: null,
        partStates: { hideParts: true },
        effects: [],
      };
    }

    const isGrounded = Boolean(grounded) || armor === 0;
    const isReflect = Boolean(reflecting) && !isGrounded;

    const materialOverrides = isGrounded
      ? {
          stormDark: '#102850',
          storm: '#16467a',
          stormBright: '#2c72a8',
          eye: '#59a6bf',
          lightning: '#8cc6d9',
          orbEnergy: '#266996',
        }
      : isReflect
        ? {
            storm: '#59e0ff',
            stormBright: '#b8ffff',
            eye: '#ffffff',
            lightning: '#ffffff',
            orbEnergy: '#99f5ff',
          }
        : charging
          ? {
              storm: '#3ab5ff',
              stormBright: '#8cf2ff',
              eye: '#d9ffff',
              lightning: '#ffffff',
              orbEnergy: '#70e0ff',
            }
          : null;

    if (reducedMotion) {
      return {
        materialOverrides,
        partStates: {
          dragonBody: { frame: 0, dx: 0, dy: 0 },
          thunderOrbLeft: { frame: 0, dx: 0, dy: 0 },
          thunderOrbRight: { frame: 0, dx: 0, dy: 0 },
        },
        effects: [{ type: 'groundShadow', rx: 36, ry: 4, colorIndex: 0 }],
      };
    }

    const useNow = now > 0;
    // Slow ~2.24s coherent 8-frame serpentine idle cycle (280ms per frame)
    const bodyStep = (divMs, offset = 0) => {
      const idx = (useNow ? Math.floor(now / divMs) : frame) + offset;
      return BODY_SEQ_8[((idx % 8) + 8) % 8];
    };
    const orbStep = (divMs, offset = 0) => {
      const idx = (useNow ? Math.floor(now / divMs) : frame) + offset;
      return ORB_SEQ_6[((idx % 6) + 6) % 6];
    };

    const bodyFrame = bodyStep(charging || attacking ? 180 : 280, 0);
    const orbLeftFrame = orbStep(isGrounded ? 360 : (charging || attacking || isReflect ? 100 : 180), 0);
    const orbRightFrame = orbStep(isGrounded ? 360 : (charging || attacking || isReflect ? 100 : 180), 3);

    // Independent asynchronous elliptical orb orbits (strictly inside 158x124 master bounds)
    const tL = useNow ? now / 520 : frame * 0.9;
    const tR = useNow ? now / 580 + Math.PI : frame * 0.9 + Math.PI;
    let orbLDx = Math.round(Math.cos(tL) * 2);
    let orbLDy = Math.round(Math.sin(tL) * 3);
    let orbRDx = Math.round(Math.cos(tR) * 2);
    let orbRDy = Math.round(Math.sin(tR) * 3);

    if (charging) {
      orbLDx = 3;
      orbLDy = -3;
      orbRDx = -3;
      orbRDy = 1;
    } else if (attacking) {
      const surge = progress < 0.5 ? -2 : 1;
      orbLDx = surge;
      orbLDy = -2;
      orbRDx = surge;
      orbRDy = -1;
    } else if (hurt) {
      orbLDx = 2;
      orbLDy = 1;
      orbRDx = 2;
      orbRDy = -1;
    }

    const partStates = {
      dragonBody: { frame: bodyFrame, dx: 0, dy: 0 },
      thunderOrbLeft: { frame: orbLeftFrame, dx: orbLDx, dy: orbLDy },
      thunderOrbRight: { frame: orbRightFrame, dx: orbRDx, dy: orbRDy },
    };

    const effects = [
      { type: 'groundShadow', rx: 36, ry: 4, colorIndex: 0 },
    ];

    if (!isGrounded) {
      const sparkStep = useNow ? Math.floor(now / 170) : frame;
      if (charging) {
        effects.push(
          { type: 'linkBolt', from: 'leftThunderOrb', fromPart: 'thunderOrbLeft', to: 'leftHorn', toPart: 'dragonBody', seed: sparkStep * 3 + 1, color: '#4dd2ff', coreColor: '#ffffff' },
          { type: 'linkBolt', from: 'rightThunderOrb', fromPart: 'thunderOrbRight', to: 'rightHorn', toPart: 'dragonBody', seed: sparkStep * 3 + 2, color: '#4dd2ff', coreColor: '#ffffff' },
          { type: 'linkBolt', from: 'leftThunderOrb', fromPart: 'thunderOrbLeft', to: 'rightThunderOrb', toPart: 'thunderOrbRight', seed: sparkStep * 5 + 3, color: '#8cf5ff', coreColor: '#ffffff' },
        );
      } else if (attacking) {
        effects.push(
          { type: 'linkBolt', from: 'leftThunderOrb', fromPart: 'thunderOrbLeft', to: 'jaw', toPart: 'dragonBody', seed: sparkStep * 3 + 1, color: '#8cf5ff', coreColor: '#ffffff' },
          { type: 'linkBolt', from: 'rightThunderOrb', fromPart: 'thunderOrbRight', to: 'jaw', toPart: 'dragonBody', seed: sparkStep * 3 + 2, color: '#8cf5ff', coreColor: '#ffffff' },
          { type: 'anchorBolt', anchor: 'jaw', part: 'dragonBody', dx1: -2, dy1: 0, dx2: -24, dy2: 2, seed: sparkStep * 7, color: '#4dd2ff', coreColor: '#ffffff' },
        );
      } else if (isReflect) {
        effects.push(
          { type: 'linkBolt', from: 'leftThunderOrb', fromPart: 'thunderOrbLeft', to: 'rightThunderOrb', toPart: 'thunderOrbRight', seed: sparkStep * 5 + 1, color: '#8cf5ff', coreColor: '#ffffff' },
          { type: 'linkBolt', from: 'leftThunderOrb', fromPart: 'thunderOrbLeft', to: 'head', toPart: 'dragonBody', seed: sparkStep * 5 + 2, color: '#8cf5ff', coreColor: '#ffffff' },
        );
      } else {
        if (sparkStep % 3 === 0) {
          effects.push({ type: 'linkBolt', from: 'leftThunderOrb', fromPart: 'thunderOrbLeft', to: 'leftHorn', toPart: 'dragonBody', seed: sparkStep, color: '#4dd2ff', coreColor: '#d9ffff' });
        } else if (sparkStep % 3 === 1) {
          effects.push({ type: 'linkBolt', from: 'rightThunderOrb', fromPart: 'thunderOrbRight', to: 'rightHorn', toPart: 'dragonBody', seed: sparkStep, color: '#4dd2ff', coreColor: '#d9ffff' });
        }
        effects.push({
          type: 'groundSpark',
          dx: ((sparkStep % 3) - 1) * 14,
          y: 145,
          radius: 1,
          color: '#4dd2ff',
          coreColor: '#ffffff',
        });
      }
    }

    return {
      materialOverrides,
      partStates,
      effects,
    };
  },
});
